### 2. Service Contract Specification

We will define precise, versioned, and backwards-compatible API contracts using **Protocol Buffers for gRPC**, with clear **OpenAPI specifications for REST/JSON** mappings. This ensures interoperability and enterprise readiness.

#### Core Data Structures (Protobuf-style)

```protobuf
// File: agent_org/v1/types.proto
syntax = "proto3";
package agent_org.v1;
import "google/protobuf/timestamp.proto"; // Standard timestamp

// Represents a serialized NumPy array, ensuring type and shape integrity.
message NumpyArray {
  bytes data = 1;         // Raw byte data (e.g., float32, float64, int32)
  repeated int32 shape = 2; // Shape of the array (e.g., [2, 3])
  enum DataType {
    DT_UNKNOWN = 0;
    DT_FLOAT32 = 1;
    DT_FLOAT64 = 2;
    DT_INT32 = 3;
    DT_UINT8 = 4; // For image data, etc.
    // Extend as needed for other NumPy dtypes
  }
  DataType dtype = 3;
}

// Defines the executable logic for an agent or fitness function.
// This addresses the critical need for user-extensible code.
message CodeArtifact {
  string artifact_id = 1; // Unique, immutable ID (e.g., SHA256 hash of content)
  string name = 2;        // Human-readable name
  bytes content = 3;      // The actual code (e.g., Python module, WASM binary)
  string runtime = 4;     // Execution environment (e.g., "python:3.9", "wasm:v1")
  string entrypoint = 5;  // Function/method name to call (e.g., "execute", "fitness_function")
  string checksum = 6;    // Checksum of `content` for integrity verification
  google.protobuf.Timestamp uploaded_at = 7;
  string owner_id = 8;    // User/organization ID
}

// Genome: The genetic material of an agent.
message Genome {
  string genome_id = 1; // Unique identifier for this specific genome
  NumpyArray weights = 2; // The actual weights/parameters
  map<string, string> metadata = 3; // Optional user-defined tags
  google.protobuf.Timestamp created_at = 4;
}

// Agent: An individual actor in the system, defined by its genome and code.
message Agent {
  string agent_id = 1; // Unique identifier for this agent instance
  string genome_id = 2; // Reference to the agent's Genome
  string code_artifact_id = 3; // Reference to the CodeArtifact defining its logic
  map<string, string> metadata = 4;
  google.protobuf.Timestamp created_at = 5;
}

// AgentExecutionResult: The auditable outcome of a single agent's execution.
message AgentExecutionResult {
  string agent_id = 1;
  string execution_id = 2; // Unique ID for this specific execution attempt
  enum Status {
    EXECUTION_STATUS_UNSPECIFIED = 0;
    EXECUTION_STATUS_SUCCESS = 1;
    EXECUTION_STATUS_ERROR = 2;
    EXECUTION_STATUS_TIMEOUT = 3;
    EXECUTION_STATUS_SANDBOX_VIOLATION = 4; // Critical for auditable results
    EXECUTION_STATUS_RESOURCE_EXCEEDED = 5;
  }
  Status status = 3;
  NumpyArray output = 4;       // Agent's output if successful
  string error_message = 5;    // Detailed error message if status is ERROR
  int64 execution_time_ns = 6; // Time taken for core logic
  google.protobuf.Timestamp started_at = 7;
  google.protobuf.Timestamp completed_at = 8;
  // Resource usage metrics (from Systems Engineering's "Agent-Second")
  double cpu_cycles_consumed = 9;
  int64 memory_peak_bytes = 10;
  int64 network_io_bytes = 11;
  string telemetry_trace_id = 12; // Link to OpenTelemetry trace for this execution
}

// EvolutionaryJobSpec: Declarative specification for an evolutionary search job.
message EvolutionaryJobSpec {
  string job_id = 1; // Client-provided or server-generated
  string name = 2;
  int32 population_size = 3;
  NumpyArray genome_template = 4; // Defines initial shape/type of genomes
  string agent_code_artifact_id = 5; // Code for agent.execute()
  string fitness_code_artifact_id = 6; // Code for fitness_function()
  NumpyArray task_input_schema = 7; // Expected shape/type for task_input
  double mutation_rate = 8;
  double mutation_strength = 9;
  int32 elite_size = 10;
  int32 max_generations = 11;
  int64 timeout_seconds_per_generation = 12;
  // Future: crossover_strategy, selection_strategy, resource_limits_per_agent
}

// GenerationSummary: Summary of a single evolutionary generation.
message GenerationSummary {
  string job_id = 1;
  int32 generation_number = 2;
  double best_fitness = 3;
  string best_agent_id = 4; // ID of the best agent from this generation
  int32 population_size = 5;
  double average_fitness = 6;
  google.protobuf.Timestamp started_at = 7;
  google.protobuf.Timestamp completed_at = 8;
  string telemetry_trace_id = 9; // Link to OpenTelemetry trace for this generation
}

// EvolutionaryJobStatus: Full status and results for an evolutionary job.
message EvolutionaryJobStatus {
  string job_id = 1;
  enum JobState {
    JOB_STATE_UNSPECIFIED = 0;
    JOB_STATE_PENDING = 1;
    JOB_STATE_RUNNING = 2;
    JOB_STATE_COMPLETED = 3;
    JOB_STATE_FAILED = 4;
    JOB_STATE_CANCELLED = 5;
    JOB_STATE_TIMED_OUT = 6;
  }
  JobState state = 2;
  int32 current_generation = 3;
  repeated GenerationSummary generation_history = 4; // History of completed generations
  string final_best_agent_id = 5;
  double final_best_fitness = 6;
  string error_details = 7;
  google.protobuf.Timestamp created_at = 8;
  google.protobuf.Timestamp started_at = 9;
  google.protobuf.Timestamp completed_at = 10;
}
```

#### API Services (gRPC)

*   **`CodeArtifactService`**: For uploading, managing, and retrieving `CodeArtifact` definitions.
    *   `UploadCodeArtifact(CodeArtifact)` -> `UploadCodeArtifactResponse`
    *   `GetCodeArtifact(string artifact_id)` -> `CodeArtifact`
*   **`AgentService`**: For managing `Agent` and `Genome` entities.
    *   `CreateAgent(Agent)` -> `Agent`
    *   `GetAgent(string agent_id)` -> `Agent`
    *   `GetGenome(string genome_id)` -> `Genome`
    *   `ExecuteAgent(ExecuteAgentRequest)` -> `AgentExecutionResult` (for direct, single agent execution)
*   **`EvolutionService`**: For managing `EvolutionaryJob` lifecycles.
    *   `CreateEvolutionaryJob(EvolutionaryJobSpec)` -> `CreateEvolutionaryJobResponse`
    *   `StartEvolutionaryJob(string job_id, NumpyArray initial_task_input)` -> `StartEvolutionaryJobResponse`
    *   `GetEvolutionaryJobStatus(string job_id)` -> `EvolutionaryJobStatus`
    *   `StopEvolutionaryJob(string job_id)` -> `StopEvolutionaryJobResponse`
    *   `StreamGenerationSummaries(string job_id)` -> `stream GenerationSummary`
    *   `GetBestAgent(string job_id)` -> `Agent`

#### Telemetry Contract: OpenTelemetry Protocol (OTLP)

We will fully embrace **OTLP** for all trace, metric, and log data. Our `agent-org` runtime will emit data in this standard format.

**`agent-org` Specific Semantic Conventions (Attributes on Spans/Metrics):**

